const cp = require("child_process");
const tick = () => new Promise((r) => setTimeout(r, 20));
// rejections nobody handled, as Node.js treats them: each case runs as a child of this program.
// The same package under Node.js prints the same.
const cases = {
  async plain() { Promise.reject(new Error("nobody handled this")); await tick(); console.log("not reached"); },
  async listened() {
    process.on("unhandledRejection", (reason) => console.log("listener:", reason.message));
    Promise.reject(new Error("seen"));
    await tick();
    console.log("went on");
  },
  async handledLater() {
    const p = Promise.reject(new Error("late"));
    await null;
    p.catch((e) => console.log("caught:", e.message));
    await tick();
  },
};
module.exports = async function run() {
  const which = process.env.TOV_REJECTION_CASE;
  if (which) return cases[which]();
  for (const c of Object.keys(cases)) {
    const r = cp.spawnSync(process.execPath, process.execArgv.concat(process.argv.slice(1)), { env: { ...process.env, TOV_REJECTION_CASE: c }, encoding: "utf8" });
    console.log(c, r.status, JSON.stringify(r.stdout), r.stderr.includes("nobody handled this"));
  }
};
